css:
.print-format{
    margin: 0;
    padding: 0;
    width: 800px;
    max-height: 300px;
    left: 0;
    top: 0;
}

  .logo-container {
    width: 100%;
    display: flex;
  }
  .logo-left-margin {
    width: 100%;
    height: 100px;
  }

  .logo {
    display: block;
    width: fit-content;
    margin-left: auto;
    position: relative;
  }

html:
{% set employee = frappe.get_doc("Employee" , doc.employee) %}
<div class="certificate">
  <div class="logo-container">
    <div class="logo-left-margin"></div>
    <div class="logo">
      <img class="meril" src="/assets/lms/images/meril.svg" alt="Meril" />
      <span>More to Life</span>
    </div>
  </div>
  <div class="padding-container">
  <h2><i>Certificate of Completion</i></h2>
      <span class="addressing">This is hebery presented to</span>
      <p class="emp-name">{{ employee.employee_name }}</p>
      <span class="reasion">for completion of trainning on</span>
    <span class="time">"Ethics & Compliance" for FY. {{ frappe.utils.getdate().strftime('%Y') }} - {{ frappe.utils.getdate(frappe.utils.add_to_date(frappe.utils.today(), years=1)).strftime('%Y') }}</span>
    </div>
  
  <div class="strip strip-tl">
  </div>
   <div class="strip strip-rb">st
  </div>
</div>

<style>
@page {
        size: A5 landscape;

        /* Example of custom margins */
        margin: 0px;
    }
*{
  padding: 0;
  margin: 0;
  text-size: 25px;
}
.certificate{
  min-width: 800px;
  max-width: 800px;
  background: white;
  position: relative;
  overflow: hidden;
}

h2{
  font-size: 35px;
  text-align: center;
  font-family: serif !important;
}

.logo{
  display: block;
  width: fit-content;
  margin-left: auto;
  position: relative;
}

.logo span{
  position: absolute;
  bottom: 0;
  transform: translate(-50%, -80%);
  left: 45%;
  white-space: nowrap;
  font-family: sans-serif;
  color: #999;
}
.meril{
  width: 150px;
  font-family: sans-serif;
}

.padding-container{
  padding: 0 100px 150px;
}

.addressing, .emp-name, .reasion, .time{
  font-size: 20px;
  font-family: sans-serif;
  display: block;
}

.addressing{
  margin-top: 50px;
  color: #42505d;
}

.emp-name{
  text-align: center;
  margin: 20px 0;
}

.strip{
  position: absolute;
  width: 300px;
  height: 300px;
  background: linear-gradient(to right, #16668b 85%,#387d9c 85%);
}

.strip-tl{
  top: 0;
  left: 0;
  transform: translate(-50%, -50%) rotate(45deg);
}

.strip-rb{
  right: 0;
  bottom: 0;
  transform: translate(50%, 50%) rotate(225deg);
}
</style>
